import { readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const root = resolve(import.meta.dirname, '..')
const inline = path => readFileSync(resolve(root, path), 'utf8').replace(/^export\s+/gm, '')
const bundle = [
  '// Generated by scripts/build-draw-score.mjs. Edit handler.ts and the shared pure modules.',
  'import { createClient } from "https://esm.sh/@supabase/supabase-js@2"',
  inline('app/src/modules/draw/classMap.ts'),
  inline('app/src/modules/draw/aiScore.ts'),
  inline('app/src/modules/draw/scoringContract.ts'),
  inline('supabase/functions/draw-score/handler.ts'),
].join('\n\n')
const path = resolve(root, 'supabase/functions/draw-score/index.ts')
if (process.argv.includes('--check')) {
  if (readFileSync(path, 'utf8') !== `${bundle}\n`) {
    console.error('draw-score bundle is stale; run node scripts/build-draw-score.mjs')
    process.exit(1)
  }
  console.log('✓ draw-score bundle matches shared modules and handler')
} else {
  writeFileSync(path, `${bundle}\n`)
  console.log(`Generated draw-score: ${Buffer.byteLength(bundle)} bytes`)
}
